    }

    pub(in crate::db) fn resolve_local_binding(
        &mut self,
        range: TextRange,
    ) -> InferredTypeData<'db> {
        let Some(reference) = self.js_info.raw_binding_types.get(&range).cloned() else {
            return InferredTypeData::Unknown;
