    fn resolve_pick_or_omit(
        &mut self,
        qualifier: &TypeReferenceQualifier,
    ) -> InferredTypeData<'db> {
        let target_ty = self.resolve(&qualifier.type_parameters[0]);
        let key_ty = self.resolve(&qualifier.type_parameters[1]);
        let Some(key_names) = self.string_literal_keys(key_ty) else {
            return InferredTypeData::Unknown;
        };
        let Some(members) = self.own_members(target_ty) else {
            return InferredTypeData::Unknown;
        };

        let exact = self.has_exact_own_keys(target_ty) && self.has_exact_string_keys(key_ty);
        let result = if qualifier.is_pick() {
            InferredTypeData::pick_members(self.db, members, &key_names)
        } else {
            InferredTypeData::omit_members(self.db, members, &key_names)
        };
        self.with_key_uncertainty(result, exact)
    }

    fn resolve_partial_or_required(
        &mut self,
        qualifier: &TypeReferenceQualifier,
    ) -> InferredTypeData<'db> {
        let target_ty = self.resolve(&qualifier.type_parameters[0]);
        let Some(members) = self.own_members(target_ty) else {
            return InferredTypeData::Unknown;
        };

        let exact = self.has_exact_own_keys(target_ty);
        let result = if qualifier.is_partial() {
            InferredTypeData::with_all_optional_members(self.db, members)
        } else {
            InferredTypeData::with_all_required_members(self.db, members)
        };
        self.with_key_uncertainty(result, exact)
    }

    fn resolve_readonly(&mut self, qualifier: &TypeReferenceQualifier) -> InferredTypeData<'db> {
        let target_ty = self.resolve(&qualifier.type_parameters[0]);
        let exact = self.has_exact_own_keys(target_ty);
        let result = self
            .own_members(target_ty)
            .map_or(InferredTypeData::Unknown, |members| {
                InferredTypeData::object_from_members(self.db, members)
            });
        self.with_key_uncertainty(result, exact)
    }

    fn with_key_uncertainty(
        &self,
        ty: InferredTypeData<'db>,
        exact: bool,
    ) -> InferredTypeData<'db> {
        if !exact && let InferredTypeData::Object(object) = ty {
            return InferredTypeData::Object(
                biome_js_type_info::interned_types::InternedObject::new_with_key_uncertainty(
                    self.db,
                    object.prototype(self.db),
                    object.members(self.db).clone(),
                    object.has_unknown_members(self.db),
                    true,
                ),
            );
        }
        ty
    }

    #[expect(
        clippy::wildcard_enum_match_arm,
        reason = "Only objects with exact own keys are supported."
    )]
    fn has_exact_own_keys(&mut self, mut ty: InferredTypeData<'db>) -> bool {
        for _ in 0..MAX_LOCAL_TYPE_RESOLUTION_STEPS {
            ty = self.resolve_inferred_type(ty);
            match ty {
                InferredTypeData::Object(object) => {
                    return object.prototype(self.db).is_none()
                        && !object.has_unknown_members(self.db)
                        && !object.has_unknown_keys(self.db)
                        && object.members(self.db).iter().all(|member| {
                            member.kind.name().is_some_and(|name| {
