use std::ops::Neg;

use biome_rowan::Text;

#[derive(Clone, Debug, Default, Eq, Hash, PartialEq)]
pub struct BooleanLiteral(bool);

impl BooleanLiteral {
    #[inline]
    pub fn as_bool(&self) -> bool {
        self.0
    }

    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "true" => Some(Self(true)),
            "false" => Some(Self(false)),
            _ => None,
        }
    }
}

impl From<bool> for BooleanLiteral {
    fn from(value: bool) -> Self {
        Self(value)
    }
}

#[derive(Clone, Debug, Default, Eq, Hash, PartialEq)]
pub struct NumberLiteral(Text);

impl NumberLiteral {
    pub fn new(text: Text) -> Self {
        Self(text)
    }

    #[inline]
    pub fn as_str(&self) -> &str {
        self.0.text()
    }

    #[inline]
    pub fn text(&self) -> &Text {
        &self.0
    }

    pub fn to_f64(&self) -> Option<f64> {
        let parse = |text: &str| {
            if text == "NaN" {
                Some(f64::NAN)
            } else {
                biome_js_syntax::numbers::parse_js_number(text)
            }
        };

        let text = self.as_str();
        if let Some(text) = text.strip_prefix('-') {
            parse(text).map(Neg::neg)
        } else {
            parse(text)
        }
    }
}

#[derive(Clone, Debug, Default, Eq, Hash, PartialEq)]
pub struct RegexpLiteral {
    /// The pattern to match against.
    ///
    /// Examples:
    ///
    /// ```js
    /// const regex1 = /hello/;
    /// //     Pattern: ^^^^^
    ///
    /// const regex2 = new RegExp("world", "i");
    /// //                Pattern: ^^^^^
    /// ```
    pub pattern: Text,

    /// The flags carried by the expression.
    ///
    /// Examples:
    ///
    /// ```js
    /// const regex1 = /hello/i;
    /// //              Flag: ^
    ///
    /// const regex2 = new RegExp("world", "g");
    /// //                            Flag: ^
    /// ```
    pub flags: Text,
}

#[derive(Clone, Debug, Default, Eq, Hash, PartialEq)]
pub struct StringLiteral(Text);

impl StringLiteral {
    #[inline]
    pub fn as_str(&self) -> &str {
        self.0.text()
    }
}

// TODO: parse escape sequences
impl AsRef<Text> for StringLiteral {
    fn as_ref(&self) -> &Text {
        &self.0
    }
}

impl From<Text> for StringLiteral {
    fn from(value: Text) -> Self {
        Self(value)
    }
}

impl From<String> for StringLiteral {
    fn from(value: String) -> Self {
        Self(value.into())
    }
}

impl From<&str> for StringLiteral {
    fn from(value: &str) -> Self {
        Self(value.to_string().into())
    }
}

impl From<StringLiteral> for Text {
    fn from(value: StringLiteral) -> Self {
        value.0
    }
}

