        assert_eq!(
            NumberLiteral(Text::new_static("1234567890")).to_f64(),
            Some(1_234_567_890.0)
        );
        assert_eq!(NumberLiteral(Text::new_static("42")).to_f64(), Some(42.0));
        assert_eq!(NumberLiteral(Text::new_static("0")).to_f64(), Some(0.0));
    }

